// Find the simulator's namespace number from its URI. OPC UA guarantees the
// URI, not the number, so OFM stores addresses as nsu=... and translates
// them here (Architecture Overview §5). Step 1.4 does the same for all mappings.
const uri = "http://microsoft.com/Opc/OpcPlc/";
const ns = Array.isArray(msg.payload) ? msg.payload.indexOf(uri) : -1;
if (ns < 0) {
    node.status({ fill: "red", shape: "ring", text: "namespace not found" });
    node.error("Namespace " + uri + " not found. Server namespaces: " + JSON.stringify(msg.payload));
    return null;
}
node.status({ fill: "green", shape: "dot", text: "OpcPlc namespace is ns=" + ns });
// The five simulator nodes used by the example plant "acme".
const nodes = [
    ["SpikeData", "Double"], ["PositiveTrendData", "Double"], ["DipData", "Double"],
    ["AlternatingBoolean", "Boolean"], ["SlowUInt1", "UInt32"]
];
return [nodes.map(([id, type]) => ({ topic: "ns=" + ns + ";s=" + id, datatype: type }))];

// One readable line per value: what the ingest flow will receive.
if (msg.topic === "subscriptionId") return null;
const sc = msg.statusCode;
msg.payload = {
    node: msg.topic,
    value: msg.payload,
    quality: sc && (sc.name || String(sc)),
    sourceTimestamp: msg.sourceTimestamp,
    serverTimestamp: msg.serverTimestamp
};
return msg;
